using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using Verse;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(d==null)return "No current match; inspect natural termination.";var f=BindingFlags.Instance|BindingFlags.NonPublic;var talk=(List<string>)typeof(Dialog_MiniGame).GetField("talk",f).GetValue(d);Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;var p=(Pawn)typeof(Dialog_MiniGame).GetField("seatedPawn",f).GetValue(d);var o=(Pawn)typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(d);bool forced=false;if(talk.Count==0){forced=true;o.interactions.TryInteractWith(p,InteractionDefOf.Insult);typeof(Dialog_MiniGame).GetMethod("CollectTalk",f).Invoke(d,null);}return "forcedOnlyForTooltip="+forced+" rect="+d.windowRect+" bandHeight="+typeof(Dialog_MiniGame).GetMethod("TalkBandHeight",f).Invoke(d,null)+" lines="+string.Join(" | ",talk);}}
